const TelemetryPointCount = 961
const HousekeepingPointCount = 320

// SampleRateHz is a point's sample rate in a mode: housekeeping points follow the mode's
// housekeeping period, every other point its dictionary rate. ok is false without either.
func SampleRateHz(p TelemetryPoint, mode string) (rate float64, ok bool) {
	if p.Kind == "housekeeping" {
		if r, found := RateSetByMode[mode]; found && r.HousekeepingPeriodS != nil && *r.HousekeepingPeriodS > 0 {
			return 1.0 / *r.HousekeepingPeriodS, true
		}
	}
	if p.RateHz == nil {
		return 0, false
	}
	return *p.RateHz, true
}
